import sys
from collections import deque

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    f = int(input_data[1])

    grid = [list(input_data[i + 2]) for i in range(n)]

    if int(grid[0][0]) <= f:
        grid[0][0] = '*'
        queue = deque([(0, 0)])

        while queue:
            r, c = queue.popleft()

            for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < n and grid[nr][nc] != '*':
                    if int(grid[nr][nc]) <= f:
                        grid[nr][nc] = '*'
                        queue.append((nr, nc))

    for row in grid:
        sys.stdout.write("".join(row) + "\n")

if __name__ == '__main__':
    main()
